import ast
import operator

_ALLOWED_BINOPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_ALLOWED_UNARYOPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}
MAX_EXPR_LEN = 256
MAX_DEPTH = 32
MAX_POW_EXPONENT = 1024


class UnsafeExpressionError(ValueError):
    """Raised when an expression contains a disallowed construct."""


def _check(node, depth):
    if depth > MAX_DEPTH:
        raise UnsafeExpressionError("expression too deeply nested")
    if isinstance(node, ast.Expression):
        return _check(node.body, depth + 1)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise UnsafeExpressionError("only numeric constants are allowed")
        return
    if isinstance(node, ast.BinOp):
        handler = _ALLOWED_BINOPS.get(type(node.op))
        if handler is None:
            raise UnsafeExpressionError("operator not permitted")
        _check(node.left, depth + 1)
        _check(node.right, depth + 1)
        return
    if isinstance(node, ast.UnaryOp):
        if type(node.op) not in _ALLOWED_UNARYOPS:
            raise UnsafeExpressionError("unary operator not permitted")
        _check(node.operand, depth + 1)
        return
    raise UnsafeExpressionError("construct not permitted")


def safe_eval(expression):
    if not isinstance(expression, str) or not expression.strip():
        raise UnsafeExpressionError("expression must be a non-empty string")
    if len(expression) > MAX_EXPR_LEN:
        raise UnsafeExpressionError("expression exceeds maximum length")
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError:
        raise UnsafeExpressionError("invalid expression syntax") from None
    _check(tree, 0)
    compiled = compile(tree, "<expr>", "eval")
    return eval(compiled, {"__builtins__": {}}, {})

