import ast
import operator

_ALLOWED_BINOPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_ALLOWED_UNARY = {ast.UAdd: operator.pos, ast.USub: operator.neg}
MAX_EXPR_LEN = 1000
MAX_DEPTH = 50
MAX_EXPONENT = 1000


def validate_expression(expr: str) -> ast.Expression:
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    if len(expr) > MAX_EXPR_LEN:
        raise ValueError("expression too long")
    try:
        tree = ast.parse(expr, mode="eval")
    except SyntaxError as e:
        raise ValueError(f"invalid syntax: {e}") from e
    _check_depth(tree.body, 0)
    return tree


def _check_depth(node, depth):
    if depth > MAX_DEPTH:
        raise ValueError("expression nesting too deep")
    for child in ast.iter_child_nodes(node):
        _check_depth(child, depth + 1)


def safe_eval(expr: str):
    tree = validate_expression(expr)
    return _eval_node(tree.body)


def _eval_node(node):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise ValueError("only numeric constants allowed")
        return node.value
    if isinstance(node, ast.BinOp):
        op_type = type(node.op)
        if op_type not in _ALLOWED_BINOPS:
            raise ValueError(f"operator not allowed: {op_type.__name__}")
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        if op_type is ast.Pow and abs(right) > MAX_EXPONENT:
            raise ValueError("exponent too large")
        return _ALLOWED_BINOPS[op_type](left, right)
    if isinstance(node, ast.UnaryOp):
        op_type = type(node.op)
        if op_type not in _ALLOWED_UNARY:
            raise ValueError(f"unary operator not allowed: {op_type.__name__}")
        return _ALLOWED_UNARY[op_type](_eval_node(node.operand))
    raise ValueError(f"expression node not allowed: {type(node).__name__}")

import ast
import operator as op

# Whitelisted binary/unary operators
BIN_OPS = {
    ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul,
    ast.Div: op.truediv, ast.FloorDiv: op.floordiv,
    ast.Mod: op.mod, ast.Pow: op.pow,
}
UNARY_OPS = {ast.UAdd: op.pos, ast.USub: op.neg}

MAX_LEN = 200
MAX_DEPTH = 20
MAX_POW_EXP = 1000

class UnsafeExpression(Exception):
    pass

def _check_depth(node, depth=0):
    if depth > MAX_DEPTH:
        raise UnsafeExpression("expression too deeply nested")
    for child in ast.iter_child_nodes(node):
        _check_depth(child, depth + 1)

def safe_eval(expression, variables=None):
    if not isinstance(expression, str) or len(expression) > MAX_LEN:
        raise UnsafeExpression("invalid or oversized expression")
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError as e:
        raise UnsafeExpression(f"invalid syntax: {e}")
    _check_depth(tree)
    return _eval_node(tree.body, variables or {})

def _eval_node(node, variables):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise UnsafeExpression("only int/float constants allowed")
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in variables:
            raise UnsafeExpression(f"unknown variable: {node.id}")
        return variables[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in BIN_OPS:
        left = _eval_node(node.left, variables)
        right = _eval_node(node.right, variables)
        if isinstance(node.op, ast.Pow) and abs(right) > MAX_POW_EXP:
            raise UnsafeExpression("exponent too large")
        try:
            return BIN_OPS[type(node.op)](left, right)
        except ZeroDivisionError:
            raise UnsafeExpression("division by zero")
        except OverflowError:
            raise UnsafeExpression("numeric overflow")
    if isinstance(node, ast.UnaryOp) and type(node.op) in UNARY_OPS:
        return UNARY_OPS[type(node.op)](_eval_node(node.operand, variables))
    raise UnsafeExpression(f"disallowed node: {type(node).__name__}")

import ast
import operator

# --- Example A: UNSAFE, never do this ---
def unsafe_eval(user_expr: str):
    return eval(user_expr)  # CWE-95: arbitrary code execution


# --- Example B: allow-list AST evaluator with resource ceilings ---
MAX_LEN = 256
MAX_NODES = 64
MAX_DEPTH = 12

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_UNARY_OPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}

_ALLOWED_FUNCS = {
    "abs": abs,
    "min": min,
    "max": max,
    "round": round,
    "sqrt": math.sqrt,
    "log": math.log,
    "exp": math.exp,
}


class ExpressionError(ValueError):
    """Safe, non-leaking error surfaced to callers."""


def _check_depth(node: ast.AST, depth: int = 0) -> int:
    depth += 1
    if depth > MAX_DEPTH:
        raise ExpressionError("expression nesting too deep")
    for child in ast.iter_child_nodes(node):
        depth = max(depth, _check_depth(child, depth))
    return depth


def validate_expression(text: str) -> ast.Expression:
    if not isinstance(text, str):
        raise ExpressionError("expression must be a string")
    if len(text) > MAX_LEN:
        raise ExpressionError("expression too long")
    try:
        tree = ast.parse(text, mode="eval")
    except SyntaxError:
        raise ExpressionError("invalid expression syntax") from None
    if sum(1 for _ in ast.walk(tree)) > MAX_NODES:
        raise ExpressionError("expression too complex")
    _check_depth(tree)
    _assert_nodes_allowed(tree)
    return tree


def _assert_nodes_allowed(tree: ast.Expression) -> None:
    for node in ast.walk(tree):
        if isinstance(node, (ast.Expression, ast.Load, ast.Constant)):
            continue
        if isinstance(node, ast.BinOp) and type(node.op) in _BIN_OPS:
            continue
        if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY_OPS:
            continue
        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name):
                raise ExpressionError("only direct calls to allowed functions")
            if node.func.id not in _ALLOWED_FUNCS:
                raise ExpressionError(f"function not allowed: {node.func.id}")
            if node.keywords:
                raise ExpressionError("keyword arguments not allowed")
            continue
        if isinstance(node, ast.Name) and node.id in _ALLOWED_FUNCS:
            continue
        raise ExpressionError(f"disallowed construct: {type(node).__name__}")


def evaluate_expression(text: str) -> float:
    tree = validate_expression(text)
    value = _eval_node(tree.body)

    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ExpressionError("result is not a real number")
    if isinstance(value, float) and not math.isfinite(value):
        raise ExpressionError("result is not finite")
    if isinstance(value, (int, float)) and abs(value) > 1e308:
        raise ExpressionError("result out of range")
    return value


def _eval_node(node: ast.AST):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise ExpressionError("only numeric literals allowed")
        return node.value
    if isinstance(node, ast.Name):
        raise ExpressionError("bare names not allowed")
    if isinstance(node, ast.BinOp):
        op = _BIN_OPS.get(type(node.op))
        if op is None:
            raise ExpressionError("operator not allowed")
        left, right = _eval_node(node.left), _eval_node(node.right)
        if op is operator.pow and isinstance(right, (int, float)) and abs(right) > 64:
            raise ExpressionError("exponent too large")
        try:
            return op(left, right)
        except ZeroDivisionError:
            raise ExpressionError("division by zero") from None
        except (OverflowError, ValueError):
            raise ExpressionError("arithmetic error") from None
    if isinstance(node, ast.UnaryOp):
        op = _UNARY_OPS.get(type(node.op))
        if op is None:
            raise ExpressionError("operator not allowed")
        return op(_eval_node(node.operand))
    if isinstance(node, ast.Call):
        func = _ALLOWED_FUNCS[node.func.id]
        args = [_eval_node(a) for a in node.args]
        try:
            return func(*args)
        except (ZeroDivisionError, OverflowError, ValueError):
            raise ExpressionError("arithmetic error") from None
    raise ExpressionError("disallowed construct")

